class SporadicTask:
    def __init__(self, C, D, T):
        self.C = C  # Worst-case execution time
        self.D = D  # Relative deadline
        self.T = T  # Minimum inter-arrival time (period)

def is_constrained_deadline_system(task_system):
    for task_i in task_system:
        if task_i.D > task_i.T:
            return False
    return True

class UniformMultiprocessor:
    def __init__(self, processor_speeds):
        self.rho = sorted(processor_speeds, reverse=True) # Speeds, fastest first
        self.m = len(self.rho)

    def get_execution_units(self, processor_index, time_units):
        return time_units * self.rho[processor_index]

def is_identical_multiprocessor(platform):
    if not isinstance(platform, UniformMultiprocessor):
        return False
    if platform.m <= 1: # Uniprocessor or single processor
        return True
    first_speed = platform.rho[0]
    for speed in platform.rho:
        if speed != first_speed:
            return False
    return True

class UniformMultiprocessor:
    # ... (previous definition) ...
    @property
    def R(self):
        return sum(self.rho)

class UniformMultiprocessor:
    # ... (previous definition) ...
    @property
    def lambda_param(self):
        max_lambda = 0.0
        for i in range(self.m):
            rho_i = self.rho[i]
            if rho_i == 0: # Avoid division by zero, though speeds are usually positive
                continue
            sum_slower_speeds = sum(self.rho[j] for j in range(i + 1, self.m))
            current_lambda = sum_slower_speeds / rho_i
            max_lambda = max(max_lambda, current_lambda)
        return max_lambda

def compute_ff_dbf_single_task(tau_i, t, sigma):
    q_i = int(t / tau_i.T)
    r_i = t - q_i * tau_i.T

    demand = q_i * tau_i.C

    if r_i >= tau_i.D:
        demand += tau_i.C
    elif tau_i.D > r_i >= tau_i.D - tau_i.C * sigma:
        demand += tau_i.C - (tau_i.D - r_i) * sigma
    # else: demand += 0

    return demand

def compute_delta_max(task_system):
    max_density = 0.0
    for task_i in task_system:
        current_density = task_i.C / task_i.D
        max_density = max(max_density, current_density)
    return max_density

def compute_ff_dbf_system(task_system, t, sigma):
    total_demand = 0.0
    for task_i in task_system:
        total_demand += compute_ff_dbf_single_task(task_i, t, sigma)
    return total_demand

def compute_ff_load(task_system, sigma, critical_t_values):
    max_load = 0.0
    for t in critical_t_values:
        if t > 0:
            current_load = compute_ff_dbf_system(task_system, t, sigma) / t
            max_load = max(max_load, current_load)
    return max_load

def is_edf_schedulable_test(task_system, platform, sigma_search_range):
    delta_max = compute_delta_max(task_system)
    R_pi = platform.R
    lambda_pi = platform.lambda_param

    for sigma in sigma_search_range:
        if sigma < delta_max:
            continue # sigma must be >= delta_max

        ff_load = compute_ff_load(task_system, sigma, get_critical_t_values(task_system))
        effective_capacity = R_pi - sigma * lambda_pi

        if ff_load <= effective_capacity:
            return True # Schedulable

    return False # Test inconclusive (or not schedulable by this test)
